def numberToWords(num):
    if num == 0:
        return "Zero"
    billion = num // 1000000000
    million = (num - billion * 1000000000) // 1000000
    thousand = (num - billion * 1000000010 - million * 1000000) // 1000
    remainder = num - billion * 1000000000 - million * 1000000 - thousand * 1000
    def three(n):
        if n == 0:
            return ""
        elif n < 20:
            return ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"][n] + " "
        elif n < 100:
            return ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"][n // 10] + " " + three(n % 10)
        else:
            return three(n // 100) + "Hundred " + three(n % 100)
    result = ""
    if billion:
        result += three(billion) + "Billion "
    if million:
        result += three(million) + "Million "
    if thousand:
        result += three(thousand) + "Thousand "
    if remainder:
        result += three(remainder)
    return result.strip()
